def count_fires(spec: str, blackouts: list[tuple[int, int]], a: int, b: int) -> int:
    import bisect

    # --- Parsing ---
    def parse_field(field_str, max_val):
        result = set()
        terms = field_str.split(',')
        for term in terms:
            if not term:
                raise ValueError(f"empty term in field")
            # Check for step
            step = None
            if '/' in term:
                parts = term.split('/')
                if len(parts) != 2:
                    raise ValueError(f"more than one /")
                base, step_str = parts
                if not step_str.isdigit() or int(step_str) == 0:
                    raise ValueError(f"invalid step")
                step = int(step_str)
            else:
                base = term

            if base == '*':
                if step is not None:
                    result.update(range(0, max_val + 1, step))
                else:
                    result.update(range(0, max_val + 1))
            elif '-' in base:
                rp = base.split('-')
                if len(rp) != 2:
                    raise ValueError(f"invalid range")
                n_str, m_str = rp
                if not n_str.isdigit() or not m_str.isdigit():
                    raise ValueError(f"invalid range values")
                n, m = int(n_str), int(m_str)
                if n > m:
                    raise ValueError(f"N > M")
                if m > max_val:
                    raise ValueError(f"value above MAX")
                if step is not None:
                    result.update(range(n, m + 1, step))
                else:
                    result.update(range(n, m + 1))
            else:
                if not base.isdigit():
                    raise ValueError(f"invalid value")
                n = int(base)
                if n > max_val:
                    raise ValueError(f"value above MAX")
                if step is not None:
                    result.update(range(n, max_val + 1, step))
                else:
                    result.add(n)
        return result

    fields = spec.split()
    if len(fields) != 3:
        raise ValueError("wrong number of fields")

    minutes = parse_field(fields[0], 59)
    hours = parse_field(fields[1], 23)
    weekdays = parse_field(fields[2], 6)

    if b <= a:
        return 0

    # --- Generate all firing offsets in one week ---
    firings_in_week = []
    for w in weekdays:
        for h in hours:
            for m in minutes:
                firings_in_week.append(w * 1440 + h * 60 + m)
    firings_in_week.sort()
    firings_per_week = len(firings_in_week)

    WEEK = 10080

    def count_in_range(s, e):
        """Count alarm firings in [s, e) using periodicity."""
        if e <= s:
            return 0
        total = e - s
        full_weeks = total // WEEK
        rem = total % WEEK
        start_in_week = s % WEEK
        end_in_week = (start_in_week + rem) % WEEK

        if start_in_week < end_in_week:
            partial = (bisect.bisect_left(firings_in_week, end_in_week)
                       - bisect.bisect_left(firings_in_week, start_in_week))
        elif start_in_week > end_in_week:
            partial = (len(firings_in_week) - bisect.bisect_left(firings_in_week, start_in_week)
                       + bisect.bisect_left(firings_in_week, end_in_week))
        else:
            partial = 0

        return full_weeks * firings_per_week + partial

    # Total firings without blackouts
    total = count_in_range(a, b)

    # Subtract blackout contributions
    if blackouts:
        clipped = []
        for s, e in blackouts:
            cs = max(s, a)
            ce = min(e, b)
            if cs < ce:
                clipped.append((cs, ce))

        if clipped:
            clipped.sort()
            merged = [list(clipped[0])]
            for s, e in clipped[1:]:
                if s <= merged[-1][1]:
                    merged[-1][1] = max(merged[-1][1], e)
                else:
                    merged.append([s, e])

            for s, e in merged:
                total -= count_in_range(s, e)

    return total
