class FairQueue:
    WAITING = "WAITING"
    PAUSED = "PAUSED"
    RUNNING = "RUNNING"

    def __init__(self, aging: int, cap: int):
        self.aging = aging
        self.cap = cap
        self.jobs: dict[str, dict] = {}
        self._enqueue_counter = 0

    def _waited_at(self, job: dict, t: int) -> int:
        return job["accumulated_waited"] + (t - job["waiting_since"])

    def _effective_priority(self, job: dict, t: int) -> int:
        waited = self._waited_at(job, t)
        return job["base"] + min(self.cap, waited // self.aging)

    def _finalize_wait(self, job: dict, t: int) -> None:
        job["accumulated_waited"] += t - job["waiting_since"]
        job["waiting_since"] = None

    def _rank_key(self, job: dict, t: int):
        eff = self._effective_priority(job, t)
        waited = self._waited_at(job, t)
        return (-eff, -waited, job["enqueue_order"])

    def submit(self, job: str, priority: int, t: int) -> None:
        if job in self.jobs:
            raise ValueError(f"Job '{job}' already exists")
        self.jobs[job] = {
            "base": priority,
            "state": self.WAITING,
            "accumulated_waited": 0,
            "waiting_since": t,
            "enqueue_order": self._enqueue_counter,
        }
        self._enqueue_counter += 1

    def start(self, t: int):
        waiting = [(name, j) for name, j in self.jobs.items()
                   if j["state"] == self.WAITING]
        if not waiting:
            return None
        waiting.sort(key=lambda x: self._rank_key(x[1], t))
        name, job = waiting[0]
        self._finalize_wait(job, t)
        job["state"] = self.RUNNING
        return name

    def finish(self, job: str, t: int) -> None:
        if job not in self.jobs:
            raise KeyError(job)
        if self.jobs[job]["state"] != self.RUNNING:
            raise KeyError(job)
        del self.jobs[job]

    def requeue(self, job: str, t: int) -> None:
        if job not in self.jobs:
            raise KeyError(job)
        j = self.jobs[job]
        if j["state"] != self.RUNNING:
            raise KeyError(job)
        j["base"] -= 1
        j["state"] = self.WAITING
        j["waiting_since"] = t
        j["enqueue_order"] = self._enqueue_counter
        self._enqueue_counter += 1

    def pause(self, job: str, t: int) -> bool:
        if job not in self.jobs:
            raise KeyError(job)
        j = self.jobs[job]
        if j["state"] == self.PAUSED:
            return False
        if j["state"] != self.WAITING:
            raise KeyError(job)
        self._finalize_wait(j, t)
        j["state"] = self.PAUSED
        return True

    def resume(self, job: str, t: int) -> bool:
        if job not in self.jobs:
            raise KeyError(job)
        j = self.jobs[job]
        if j["state"] == self.WAITING:
            return False
        if j["state"] != self.PAUSED:
            raise KeyError(job)
        j["state"] = self.WAITING
        j["waiting_since"] = t
        return True

    def cancel(self, job: str) -> bool:
        if job not in self.jobs:
            return False
        del self.jobs[job]
        return True

    def queue(self, t: int) -> list[tuple[str, int]]:
        waiting = [(name, j) for name, j in self.jobs.items()
                   if j["state"] == self.WAITING]
        waiting.sort(key=lambda x: self._rank_key(x[1], t))
        return [(name, self._effective_priority(j, t)) for name, j in waiting]
