def run_script(source: str, max_steps: int) -> tuple[list[int], str]:
    # Phase 1: Parse and static check
    lines = source.split("\n")
    parsed_lines = []
    for line in lines:
        tokens = line.split()
        if not tokens:
            continue
        if tokens[0].startswith("#"):
            continue
        parsed_lines.append(tokens)

    def is_int_literal(tok):
        if tok.startswith('-'):
            return len(tok) > 1 and tok[1:].isdigit()
        return tok.isdigit()

    def is_var_name(tok):
        return tok.isalpha() and tok.islower()

    VALID_OPS = {'+', '-', '*', '/', '%', '<', '>', '='}

    def validate_expr(tokens):
        if len(tokens) == 0:
            raise ValueError("empty expression")
        if len(tokens) % 2 == 0:
            raise ValueError("wrong alternation in expression")
        for i, tok in enumerate(tokens):
            if i % 2 == 0:
                if not (is_int_literal(tok) or is_var_name(tok)):
                    raise ValueError(f"bad operand: {tok}")
            else:
                if tok not in VALID_OPS:
                    raise ValueError(f"bad operator: {tok}")

    program = []
    block_stack = []  # list of dicts: {'type', 'index', 'else_index'}

    for i, tokens in enumerate(parsed_lines):
        first = tokens[0]

        if first == 'set':
            if len(tokens) < 4:
                raise ValueError("malformed set")
            name = tokens[1]
            if not is_var_name(name):
                raise ValueError("malformed set: bad name")
            if tokens[2] != '=':
                raise ValueError("malformed set: expected =")
            expr = tokens[3:]
            validate_expr(expr)
            program.append(('set', name, expr))

        elif first == 'emit':
            if len(tokens) < 2:
                raise ValueError("empty expression")
            expr = tokens[1:]
            validate_expr(expr)
            program.append(('emit', expr))

        elif first == 'if':
            if len(tokens) < 2:
                raise ValueError("empty expression")
            expr = tokens[1:]
            validate_expr(expr)
            block_stack.append({'type': 'if', 'index': i, 'else_index': None})
            program.append(('if', expr))

        elif first == 'while':
            if len(tokens) < 2:
                raise ValueError("empty expression")
            expr = tokens[1:]
            validate_expr(expr)
            block_stack.append({'type': 'while', 'index': i, 'else_index': None})
            program.append(('while', expr))

        elif first == 'else':
            if len(tokens) != 1:
                raise ValueError("extra tokens after else")
            if not block_stack or block_stack[-1]['type'] != 'if' or block_stack[-1]['else_index'] is not None:
                raise ValueError("else does not belong to open if without else")
            block_stack[-1]['else_index'] = i
            program.append(('else',))

        elif first == 'end':
            if len(tokens) != 1:
                raise ValueError("extra tokens after end")
            if not block_stack:
                raise ValueError("end with no open block")
            block_stack.pop()
            program.append(('end',))

        elif first == 'break':
            if len(tokens) != 1:
                raise ValueError("extra tokens after break")
            if not any(b['type'] == 'while' for b in block_stack):
                raise ValueError("break not inside while")
            program.append(('break',))

        elif first == 'skip':
            if len(tokens) != 1:
                raise ValueError("extra tokens after skip")
            if not any(b['type'] == 'while' for b in block_stack):
                raise ValueError("skip not inside while")
            program.append(('skip',))

        elif first == 'halt':
            if len(tokens) != 1:
                raise ValueError("extra tokens after halt")
            program.append(('halt',))

        else:
            raise ValueError(f"unknown first token: {first}")

    if block_stack:
        raise ValueError("block still open at end")

    # Phase 1.5: Pre-compute jump targets
    if_jumps = {}     # if_index -> (else_body_start or None, end_index)
    while_jumps = {}  # while_index -> end_index
    else_jumps = {}   # else_index -> end_index
    break_temp = {}   # break_index -> while_index
    skip_jumps = {}   # skip_index -> while_index

    stack2 = []  # list of (type, index, else_index)

    for i, stmt in enumerate(program):
        stype = stmt[0]
        if stype == 'if':
            stack2.append(('if', i, None))
        elif stype == 'while':
            stack2.append(('while', i, None))
        elif stype == 'else':
            stack2[-1] = ('if', stack2[-1][1], i)
        elif stype == 'end':
            btype, bidx, eidx = stack2.pop()
            if btype == 'if':
                else_start = (eidx + 1) if eidx is not None else None
                if_jumps[bidx] = (else_start, i)
                if eidx is not None:
                    else_jumps[eidx] = i
            else:
                while_jumps[bidx] = i
        elif stype == 'break':
            for j in range(len(stack2) - 1, -1, -1):
                if stack2[j][0] == 'while':
                    break_temp[i] = stack2[j][1]
                    break
        elif stype == 'skip':
            for j in range(len(stack2) - 1, -1, -1):
                if stack2[j][0] == 'while':
                    skip_jumps[i] = stack2[j][1]
                    break

    # Resolve break targets
    break_jumps = {}
    for i, widx in break_temp.items():
        break_jumps[i] = while_jumps[widx] + 1

    # Phase 2: Execute
    def get_operand(tok, vars_):
        if is_int_literal(tok):
            return int(tok)
        return vars_.get(tok, 0)

    def eval_expr(tokens, vars_):
        result = get_operand(tokens[0], vars_)
        for k in range(1, len(tokens), 2):
            op = tokens[k]
            right = get_operand(tokens[k + 1], vars_)
            if op == '+':
                result = result + right
            elif op == '-':
                result = result - right
            elif op == '*':
                result = result * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError
                result = result // right
            elif op == '%':
                if right == 0:
                    raise ZeroDivisionError
                result = result % right
            elif op == '<':
                result = 1 if result < right else 0
            elif op == '>':
                result = 1 if result > right else 0
            elif op == '=':
                result = 1 if result == right else 0
        return result

    emitted = []
    variables = {}
    pc = 0
    steps = 0
    n = len(program)

    while pc < n:
        stmt = program[pc]
        stype = stmt[0]

        if stype == 'set':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            _, name, expr = stmt
            try:
                val = eval_expr(expr, variables)
            except ZeroDivisionError:
                return emitted, "error"
            variables[name] = val
            pc += 1

        elif stype == 'emit':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            _, expr = stmt
            try:
                val = eval_expr(expr, variables)
            except ZeroDivisionError:
                return emitted, "error"
            emitted.append(val)
            pc += 1

        elif stype == 'if':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            _, expr = stmt
            try:
                val = eval_expr(expr, variables)
            except ZeroDivisionError:
                return emitted, "error"
            else_start, end_idx = if_jumps[pc]
            if val != 0:
                pc += 1
            else:
                if else_start is not None:
                    pc = else_start
                else:
                    pc = end_idx + 1

        elif stype == 'else':
            pc = else_jumps[pc] + 1

        elif stype == 'while':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            _, expr = stmt
            try:
                val = eval_expr(expr, variables)
            except ZeroDivisionError:
                return emitted, "error"
            end_idx = while_jumps[pc]
            if val != 0:
                pc += 1
            else:
                pc = end_idx + 1

        elif stype == 'end':
            pc += 1

        elif stype == 'break':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            pc = break_jumps[pc]

        elif stype == 'skip':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            pc = skip_jumps[pc]

        elif stype == 'halt':
            if steps >= max_steps:
                return emitted, "limit"
            steps += 1
            return emitted, "halt"

    return emitted, "done"
