def eval_tally(src: str, env: dict) -> int:
    TWO_CHAR_OPS = {'<=', '>=', '==', '!='}
    SINGLE_CHAR_OPS = set('+-*/%^()?!&|<>:')
    CMP_OPS = {'<', '<=', '>', '>=', '==', '!='}

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
            elif c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j]), i))
                i = j
            elif c.isalpha() or c == '_':
                j = i
                while j < n and (s[j].isalpha() or s[j].isdigit() or s[j] == '_'):
                    j += 1
                tokens.append(('NAME', s[i:j], i))
                i = j
            else:
                if i + 1 < n and s[i:i+2] in TWO_CHAR_OPS:
                    tokens.append(('OP', s[i:i+2], i))
                    i += 2
                elif c in SINGLE_CHAR_OPS:
                    tokens.append(('OP', c, i))
                    i += 1
                else:
                    tokens.append(('ILLEGAL', c, i))
                    i += 1
        return tokens

    class Parser:
        def __init__(self, tokens, src_len):
            self.tokens = tokens
            self.pos = 0
            self.src_len = src_len

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def expect_op(self, ops):
            tok = self.peek()
            if tok is None:
                raise ValueError("syntax", self.src_len)
            if tok[0] != 'OP' or tok[1] not in ops:
                raise ValueError("syntax", tok[2])
            self.pos += 1
            return tok

        def parse_expr(self):
            return self.parse_ternary()

        def parse_ternary(self):
            cond = self.parse_or()
            tok = self.peek()
            if tok is not None and tok[0] == 'OP' and tok[1] == '?':
                self.pos += 1
                then_e = self.parse_expr()
                self.expect_op({':'})
                else_e = self.parse_expr()
                return ('ternary', cond, then_e, else_e)
            return cond

        def parse_or(self):
            left = self.parse_and()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'OP' and tok[1] == '|':
                    self.pos += 1
                    right = self.parse_and()
                    left = ('binop', '|', tok[2], left, right)
                else:
                    break
            return left

        def parse_and(self):
            left = self.parse_cmp()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'OP' and tok[1] == '&':
                    self.pos += 1
                    right = self.parse_cmp()
                    left = ('binop', '&', tok[2], left, right)
                else:
                    break
            return left

        def parse_cmp(self):
            left = self.parse_add()
            tok = self.peek()
            if tok is not None and tok[0] == 'OP' and tok[1] in CMP_OPS:
                self.pos += 1
                right = self.parse_add()
                return ('binop', tok[1], tok[2], left, right)
            return left

        def parse_add(self):
            left = self.parse_mul()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'OP' and tok[1] in ('+', '-'):
                    self.pos += 1
                    right = self.parse_mul()
                    left = ('binop', tok[1], tok[2], left, right)
                else:
                    break
            return left

        def parse_mul(self):
            left = self.parse_unary()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'OP' and tok[1] in ('*', '/', '%'):
                    self.pos += 1
                    right = self.parse_unary()
                    left = ('binop', tok[1], tok[2], left, right)
                else:
                    break
            return left

        def parse_unary(self):
            ops = []
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'OP' and tok[1] in ('-', '!'):
                    ops.append(tok[1])
                    self.pos += 1
                else:
                    break
            operand = self.parse_power()
            for op in reversed(ops):
                operand = ('unop', op, operand)
            return operand

        def parse_power(self):
            left = self.parse_atom()
            tok = self.peek()
            if tok is not None and tok[0] == 'OP' and tok[1] == '^':
                self.pos += 1
                right = self.parse_unary()
                return ('power', tok[2], left, right)
            return left

        def parse_atom(self):
            tok = self.peek()
            if tok is None:
                raise ValueError("syntax", self.src_len)
            if tok[0] == 'INT':
                self.pos += 1
                return ('int', tok[1])
            elif tok[0] == 'NAME':
                self.pos += 1
                return ('name', tok[1], tok[2])
            elif tok[0] == 'OP' and tok[1] == '(':
                self.pos += 1
                e = self.parse_expr()
                self.expect_op({')'})
                return e
            else:
                raise ValueError("syntax", tok[2])

    def evaluate(node, env):
        tag = node[0]
        if tag == 'int':
            return node[1]
        elif tag == 'name':
            name, pos = node[1], node[2]
            if name not in env:
                raise ValueError("name", pos)
            return env[name]
        elif tag == 'unop':
            op, operand = node[1], node[2]
            val = evaluate(operand, env)
            if op == '-':
                return -val
            else:  # '!'
                return 1 if val == 0 else 0
        elif tag == 'power':
            op_pos, left, right = node[1], node[2], node[3]
            base = evaluate(left, env)
            exp = evaluate(right, env)
            if exp < 0:
                raise ValueError("exp", op_pos)
            return base ** exp
        elif tag == 'binop':
            op, op_pos, left, right = node[1], node[2], node[3], node[4]
            if op == '&':
                a = evaluate(left, env)
                if a == 0:
                    return 0
                b = evaluate(right, env)
                return 1 if b != 0 else 0
            elif op == '|':
                a = evaluate(left, env)
                if a != 0:
                    return 1
                b = evaluate(right, env)
                return 1 if b != 0 else 0
            else:
                a = evaluate(left, env)
                b = evaluate(right, env)
                if op == '+':
                    return a + b
                elif op == '-':
                    return a - b
                elif op == '*':
                    return a * b
                elif op == '/':
                    if b == 0:
                        raise ValueError("div", op_pos)
                    q = abs(a) // abs(b)
                    if (a < 0) != (b < 0):
                        q = -q
                    return q
                elif op == '%':
                    if b == 0:
                        raise ValueError("div", op_pos)
                    q = abs(a) // abs(b)
                    if (a < 0) != (b < 0):
                        q = -q
                    return a - b * q
                elif op == '<':
                    return 1 if a < b else 0
                elif op == '<=':
                    return 1 if a <= b else 0
                elif op == '>':
                    return 1 if a > b else 0
                elif op == '>=':
                    return 1 if a >= b else 0
                elif op == '==':
                    return 1 if a == b else 0
                elif op == '!=':
                    return 1 if a != b else 0
        elif tag == 'ternary':
            cond, then_e, else_e = node[1], node[2], node[3]
            c = evaluate(cond, env)
            if c != 0:
                return evaluate(then_e, env)
            else:
                return evaluate(else_e, env)

    tokens = tokenize(src)
    parser = Parser(tokens, len(src))
    ast = parser.parse_expr()
    if parser.pos < len(parser.tokens):
        raise ValueError("syntax", parser.tokens[parser.pos][2])
    return evaluate(ast, env)
