from collections import deque

def last_link_times(n: int, cables: list[tuple[int, int, int]], pairs: list[tuple[int, int]]) -> list:
    if n == 0:
        return [None if u == v else 0 for u, v in pairs]

    # --- Union-Find for Kruskal's (Maximum Spanning Forest) ---
    uf_parent = list(range(n))
    uf_rank = [0] * n

    def find(x):
        while uf_parent[x] != x:
            uf_parent[x] = uf_parent[uf_parent[x]]
            x = uf_parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if uf_rank[rx] < uf_rank[ry]:
            rx, ry = ry, rx
        uf_parent[ry] = rx
        if uf_rank[rx] == uf_rank[ry]:
            uf_rank[rx] += 1
        return True

    # --- Build Maximum Spanning Forest (Kruskal, descending) ---
    cables_sorted = sorted(cables, key=lambda c: c[2], reverse=True)
    adj = [[] for _ in range(n)]
    for a, b, f in cables_sorted:
        if a == b:
            continue
        if union(a, b):
            adj[a].append((b, f))
            adj[b].append((a, f))

    # --- Binary Lifting on the forest ---
    LOG = max(1, n.bit_length())
    up = [[-1] * n for _ in range(LOG)]       # up[k][v] = 2^k-th ancestor
    mn = [[float('inf')] * n for _ in range(LOG)]  # mn[k][v] = min edge v..2^k-ancestor
    depth = [-1] * n
    root = [-1] * n   # identifies which tree a node belongs to

    # BFS to fill level-0 tables and depths
    for i in range(n):
        if depth[i] != -1:
            continue
        depth[i] = 0
        root[i] = i
        q = deque([i])
        while q:
            u = q.popleft()
            for v, w in adj[u]:
                if depth[v] == -1:
                    depth[v] = depth[u] + 1
                    up[0][v] = u
                    mn[0][v] = w
                    root[v] = i
                    q.append(v)

    # Build higher levels
    for k in range(1, LOG):
        uk = up[k]
        uk1 = up[k - 1]
        mk = mn[k]
        mk1 = mn[k - 1]
        for v in range(n):
            mid = uk1[v]
            if mid != -1:
                uk[v] = uk1[mid]
                mk[v] = mk1[v] if mk1[v] < mk1[mid] else mk1[mid]
            # else stays -1 / inf

    # --- Answer queries ---
    def query(u, v):
        if u == v:
            return None
        if root[u] != root[v]:
            return 0
        # Make sure u is the deeper node
        if depth[u] < depth[v]:
            u, v = v, u
        ans = float('inf')
        # Lift u up to depth of v
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if diff >> k & 1:
                if mn[k][u] < ans:
                    ans = mn[k][u]
                u = up[k][u]
        if u == v:
            return ans
        # Lift both up until their parents are the same
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                if mn[k][u] < ans:
                    ans = mn[k][u]
                if mn[k][v] < ans:
                    ans = mn[k][v]
                u = up[k][u]
                v = up[k][v]
        # Final step: edges to LCA
        if mn[0][u] < ans:
            ans = mn[0][u]
        if mn[0][v] < ans:
            ans = mn[0][v]
        return ans

    result = []
    for u, v in pairs:
        result.append(query(u, v))
    return result
