class _Txn:
    __slots__ = ('name', 'journal')
    def __init__(self, name):
        self.name = name
        self.journal = []


class VaultKV:
    def __init__(self):
        self._data = {}
        self._holders = {}   # value -> set of keys
        self._locked = set()
        self._txns = []      # stack of _Txn

    # ---- internal helpers ----

    def _journal(self):
        return self._txns[-1].journal if self._txns else None

    def _remove_from_holders(self, key, value):
        s = self._holders.get(value)
        if s:
            s.discard(key)
            if not s:
                del self._holders[value]

    def _add_to_holders(self, key, value):
        self._holders.setdefault(value, set()).add(key)

    # ---- data methods ----

    def put(self, key, value):
        if key in self._locked:
            raise PermissionError(f"Key '{key}' is locked")
        old_value = self._data.get(key)
        existed = key in self._data
        if existed:
            self._remove_from_holders(key, old_value)
        self._data[key] = value
        self._add_to_holders(key, value)
        j = self._journal()
        if j is not None:
            j.append(("put", key, old_value, existed, value))

    def get(self, key, default=None):
        return self._data.get(key, default)

    def drop(self, key):
        if key in self._locked:
            raise PermissionError(f"Key '{key}' is locked")
        if key not in self._data:
            return False
        old_value = self._data.pop(key)
        self._remove_from_holders(key, old_value)
        j = self._journal()
        if j is not None:
            j.append(("drop", key, old_value))
        return True

    def incr(self, key, by=1):
        if key in self._locked:
            raise PermissionError(f"Key '{key}' is locked")
        old_value = self._data.get(key)
        existed = key in self._data
        if existed and isinstance(old_value, str):
            raise TypeError(f"Key '{key}' holds a string, not an integer")
        if not existed:
            old_value = 0
        new_value = old_value + by
        if existed:
            self._remove_from_holders(key, old_value)
        self._data[key] = new_value
        self._add_to_holders(key, new_value)
        j = self._journal()
        if j is not None:
            j.append(("incr", key, old_value, existed, new_value))
        return new_value

    def holders(self, value):
        return sorted(self._holders.get(value, ()))

    def size(self):
        return len(self._data)

    # ---- locks ----

    def lock(self, key):
        if key in self._locked:
            return
        self._locked.add(key)
        j = self._journal()
        if j is not None:
            j.append(("lock", key))

    def unlock(self, key):
        if key not in self._locked:
            return
        self._locked.discard(key)
        j = self._journal()
        if j is not None:
            j.append(("unlock", key))

    def locked(self, key):
        return key in self._locked

    # ---- transactions ----

    def begin(self, name=None):
        self._txns.append(_Txn(name))

    def commit(self):
        if not self._txns:
            raise RuntimeError("No transaction is open")
        txn = self._txns.pop()
        if self._txns:
            self._txns[-1].journal.extend(txn.journal)
        return len(self._txns)

    def rollback(self, name=None):
        if not self._txns:
            raise RuntimeError("No transaction is open")
        if name is None:
            txn = self._txns.pop()
            self._undo(txn.journal)
            return len(self._txns)
        # find innermost txn with this name
        idx = None
        for i in range(len(self._txns) - 1, -1, -1):
            if self._txns[i].name == name:
                idx = i
                break
        if idx is None:
            raise KeyError(f"No open transaction named '{name}'")
        # undo from innermost down to idx
        for i in range(len(self._txns) - 1, idx - 1, -1):
            self._undo(self._txns[i].journal)
        del self._txns[idx:]
        return len(self._txns)

    def depth(self):
        return len(self._txns)

    # ---- undo helper ----

    def _undo(self, journal):
        for entry in reversed(journal):
            op = entry[0]
            if op == "put":
                _, key, old_value, existed, new_value = entry
                self._remove_from_holders(key, new_value)
                if existed:
                    self._data[key] = old_value
                    self._add_to_holders(key, old_value)
                else:
                    del self._data[key]
            elif op == "drop":
                _, key, old_value = entry
                self._data[key] = old_value
                self._add_to_holders(key, old_value)
            elif op == "incr":
                _, key, old_value, existed, new_value = entry
                self._remove_from_holders(key, new_value)
                if existed:
                    self._data[key] = old_value
                    self._add_to_holders(key, old_value)
                else:
                    del self._data[key]
            elif op == "lock":
                _, key = entry
                self._locked.discard(key)
            elif op == "unlock":
                _, key = entry
                self._locked.add(key)
