from math import gcd
from functools import reduce
from itertools import combinations
from collections import defaultdict


def kth_chime(k: int, ring: list[int], mute: list[int]) -> int | None:
    if k < 1:
        raise ValueError("k must be at least 1")

    R = list(set(ring))
    M = list(set(mute))

    # The bell never chimes iff every r in R is a multiple of some m in M.
    if all(any(r % m == 0 for m in M) for r in R):
        return None

    def _lcm(a, b):
        return a * b // gcd(a, b)

    def _lcm_list(lst):
        if not lst:
            return 1
        return reduce(_lcm, lst)

    # Build f(n) = count of chiming hours in [1, n] via inclusion-exclusion:
    #   f(n) = sum_{non-empty S ⊆ R} sum_{T ⊆ M} (-1)^{|S|-1+|T|} * floor(n / LCM(S∪T))
    coeff = defaultdict(int)
    for r_size in range(1, len(R) + 1):
        for S in combinations(R, r_size):
            l_S = _lcm_list(list(S))
            for t_size in range(0, len(M) + 1):
                for T in combinations(M, t_size):
                    if T:
                        L = _lcm(l_S, _lcm_list(list(T)))
                    else:
                        L = l_S
                    sign = 1 if (r_size - 1 + t_size) % 2 == 0 else -1
                    coeff[L] += sign

    terms = [(L, c) for L, c in coeff.items() if c != 0]

    def f(n):
        total = 0
        for L, c in terms:
            total += c * (n // L)
        return total

    # Period: pattern repeats every P = LCM(R ∪ M).
    # Since the bell chimes, f(P) >= 1, so the k-th chiming hour <= k * P.
    P = _lcm_list(R + M)
    lo, hi = 1, k * P

    # Binary search for the smallest n with f(n) >= k
    # (equivalently f(n) == k, since f increases by at most 1 per step)
    while lo < hi:
        mid = (lo + hi) // 2
        if f(mid) >= k:
            hi = mid
        else:
            lo = mid + 1

    return lo
