from functools import lru_cache


def kth_arrangement(letters: str, k: int) -> str:
    if k < 1:
        raise ValueError("k must be >= 1")

    n = len(letters)

    distinct = sorted(set(letters))
    m = len(distinct)
    letter_to_idx = {ch: i for i, ch in enumerate(distinct)}

    counts = [0] * m
    for ch in letters:
        counts[letter_to_idx[ch]] += 1

    @lru_cache(maxsize=None)
    def count(rem, first, last):
        """
        rem:  tuple of remaining counts per distinct letter
        first: index of the first letter placed, or -1 if none yet
        last:  index of the last letter placed, or -1 if none yet
        Returns the number of valid linear completions (adjacent constraint
        enforced during placement; circular constraint checked at the end).
        """
        if all(x == 0 for x in rem):
            if n == 1:
                return 1
            return 1 if last != first else 0

        total = 0
        for i in range(m):
            if rem[i] == 0:
                continue
            if first == -1:
                new_rem = list(rem)
                new_rem[i] -= 1
                total += count(tuple(new_rem), i, i)
            else:
                if i == last:
                    continue
                new_rem = list(rem)
                new_rem[i] -= 1
                total += count(tuple(new_rem), first, i)
        return total

    initial_rem = tuple(counts)
    total_valid = count(initial_rem, -1, -1)

    if total_valid < k:
        return None

    # Build the answer letter by letter
    result = []
    rem = list(counts)
    first = -1
    last = -1

    for _pos in range(n):
        for i in range(m):
            if rem[i] == 0:
                continue
            if first == -1:
                new_rem = list(rem)
                new_rem[i] -= 1
                c = count(tuple(new_rem), i, i)
                if k <= c:
                    result.append(distinct[i])
                    rem = new_rem
                    first = i
                    last = i
                    break
                else:
                    k -= c
            else:
                if i == last:
                    continue
                new_rem = list(rem)
                new_rem[i] -= 1
                c = count(tuple(new_rem), first, i)
                if k <= c:
                    result.append(distinct[i])
                    rem = new_rem
                    last = i
                    break
                else:
                    k -= c

    return ''.join(result)
