from math import gcd
from itertools import product


def next_alignment(gears: list[tuple[int, int, int]], t0: int):
    if not gears:
        return t0

    def merge(r1, m1, r2, m2):
        """Merge t ≡ r1 (mod m1) with t ≡ r2 (mod m2).
        Returns (r, m) for the unique solution mod lcm(m1,m2), or None."""
        g = gcd(m1, m2)
        if (r2 - r1) % g != 0:
            return None
        m1_g = m1 // g
        m2_g = m2 // g
        rhs = (r2 - r1) // g
        if m2_g == 1:
            k = 0
        else:
            k = ((rhs % m2_g) * pow(m1_g, -1, m2_g)) % m2_g
        m = m1 * m2_g  # lcm(m1, m2)
        r = (r1 + m1 * k) % m
        return (r, m)

    best = None

    # For each gear, the open window gives width_i specific residues mod period_i
    residue_lists = []
    for period, start, width in gears:
        residue_lists.append([(start + k) % period for k in range(width)])

    # Enumerate all combinations (product of widths ≤ 20000)
    for combo in product(*residue_lists):
        # Solve the CRT system: t ≡ combo[i] (mod period_i) for each gear
        r, m = 0, 1  # identity constraint: t ≡ 0 (mod 1)
        valid = True
        for i in range(len(gears)):
            result = merge(r, m, combo[i], gears[i][0])
            if result is None:
                valid = False
                break
            r, m = result

        if not valid:
            continue

        # t ≡ r (mod m); find smallest t >= t0
        if r >= t0:
            candidate = r
        else:
            k = (t0 - r + m - 1) // m  # ceil((t0 - r) / m)
            candidate = r + k * m

        if best is None or candidate < best:
            best = candidate

    return best
