def tessel_shift(date: tuple[int, int, int], days: int) -> tuple[int, int, int, int]:
    y, m, d = date

    # Validate month
    if not (1 <= m <= 9):
        raise ValueError(f"Month {m} out of range 1..9")

    # Validate day
    if m == 4:
        max_day = 37 if _is_leap(y) else 36
    elif m in (2, 6, 8):
        max_day = 36
    else:
        max_day = 37
    if not (1 <= d <= max_day):
        raise ValueError(f"Day {d} out of range 1..{max_day} for month {m} of year {y}")

    # Convert to absolute day number (where (1,1,1) == 0)
    dn = _total_days_before(y) + _days_before_month(y, m) + (d - 1)

    # Apply shift
    dn += days

    # Convert back to date
    y2, m2, d2 = _daynum_to_date(dn)

    # Weekday: (1,1,1) is weekday 0, cycles with period 6
    wd = dn % 6

    return (y2, m2, d2, wd)


def _is_leap(y: int) -> bool:
    return (y % 6 == 0 and y % 90 != 0) or (y % 450 == 0)


def _count_div(a: int, b: int, m: int) -> int:
    """Count multiples of m in the inclusive range [a, b]."""
    if a > b:
        return 0
    return b // m - (a - 1) // m


def _count_leap(a: int, b: int) -> int:
    """Count leap years in the inclusive range [a, b]."""
    if a > b:
        return 0
    # Leap: (div by 6 and not div by 90) or div by 450
    # = div by 6  -  div by 90  +  div by 450
    return _count_div(a, b, 6) - _count_div(a, b, 90) + _count_div(a, b, 450)


def _total_days_before(y: int) -> int:
    """Return the day-number of (y, 1, 1); (1,1,1) has day-number 0."""
    if y >= 1:
        n = y - 1  # years 1 .. y-1
        return n * 329 + _count_leap(1, n)
    else:
        # years y .. 0 (all before year 1)
        n = 1 - y
        return -(n * 329 + _count_leap(y, 0))


def _days_before_month(y: int, m: int) -> int:
    """Number of days in months 1 through m-1 of year y."""
    if _is_leap(y):
        cum = (0, 37, 73, 110, 147, 184, 220, 257, 293)
    else:
        cum = (0, 37, 73, 110, 146, 183, 219, 256, 292)
    return cum[m - 1]


def _daynum_to_date(dn: int) -> tuple[int, int, int]:
    """Convert an absolute day-number back to (year, month, day)."""
    # Binary search: find the unique year y such that
    #   _total_days_before(y) <= dn < _total_days_before(y + 1)
    lo = -10**17
    hi = 10**17
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if _total_days_before(mid) <= dn:
            lo = mid
        else:
            hi = mid - 1
    y = lo

    # Day-of-year (0-based)
    day_in_year = dn - _total_days_before(y)

    if _is_leap(y):
        month_days = (37, 36, 37, 37, 37, 36, 37, 36, 37)
    else:
        month_days = (37, 36, 37, 36, 37, 36, 37, 36, 37)

    m = 1
    while day_in_year >= month_days[m - 1]:
        day_in_year -= month_days[m - 1]
        m += 1
    d = day_in_year + 1

    return (y, m, d)
