from functools import lru_cache

def count_peaky(lo: int, hi: int, peaks: int, q: int, t: int) -> int:
    if lo > hi:
        return 0

    def count_up_to(n):
        if n < 0:
            return 0
        digits = [int(c) for c in str(n)]
        k = len(digits)

        @lru_cache(maxsize=None)
        def dp(pos, started, prev2, prev1, pk, mod, tight):
            if pk > peaks:
                return 0
            if pos == k:
                if not started:
                    # Represents the number 0 (single digit '0')
                    return 1 if (pk == 0 and 0 % q == t) else 0
                else:
                    return 1 if (pk == peaks and mod == t) else 0

            upper = digits[pos] if tight else 9
            total = 0

            for d in range(upper + 1):
                new_tight = tight and (d == upper)

                if not started:
                    if d == 0:
                        # Still leading zeros
                        total += dp(pos + 1, False, -1, -1, pk, 0, new_tight)
                    else:
                        # Start the number with digit d
                        new_mod = d % q
                        total += dp(pos + 1, True, -1, d, pk, new_mod, new_tight)
                else:
                    # Check if prev1 forms a peak (needs prev2 on the left)
                    add_peak = 0
                    if prev2 != -1 and prev2 < prev1 and prev1 > d:
                        add_peak = 1
                    new_pk = pk + add_peak
                    if new_pk > peaks:
                        continue
                    new_mod = (mod * 10 + d) % q
                    total += dp(pos + 1, True, prev1, d, new_pk, new_mod, new_tight)

            return total

        return dp(0, False, -1, -1, 0, 0, True)

    return count_up_to(hi) - count_up_to(lo - 1)
