def pluck(data, query: str) -> list:
    steps = _parse_query(query)
    current = [data]
    for step in steps:
        new_current = []
        for node in current:
            new_current.extend(_apply_step(node, step))
        current = new_current
    return current


def _parse_name(s, i):
    n = len(s)
    if i >= n:
        raise ValueError("Expected name")
    c = s[i]
    if not (c == '_' or c.isalpha()):
        raise ValueError(f"Invalid name start at position {i}")
    i += 1
    start = i - 1
    while i < n and (s[i] == '_' or s[i].isalpha() or s[i].isdigit()):
        i += 1
    return s[start:i], i


def _parse_string(s, i):
    # s[i] == '"'
    i += 1
    n = len(s)
    result = []
    while i < n:
        c = s[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Unexpected end in escape sequence")
            nxt = s[i + 1]
            if nxt == '"':
                result.append('"')
                i += 2
            elif nxt == '\\':
                result.append('\\')
                i += 2
            else:
                raise ValueError(f"Invalid escape \\{nxt}")
        elif c == '"':
            return ''.join(result), i + 1
        else:
            result.append(c)
            i += 1
    raise ValueError("Unterminated string literal")


def _parse_int(s, i):
    n = len(s)
    start = i
    if i < n and s[i] == '-':
        i += 1
    if i >= n or not s[i].isdigit():
        raise ValueError(f"Invalid integer at position {start}")
    while i < n and s[i].isdigit():
        i += 1
    return int(s[start:i]), i


def _parse_filter(s, i):
    n = len(s)
    # Optional spaces after ?
    while i < n and s[i] == ' ':
        i += 1
    # Parse NAME
    name, i = _parse_name(s, i)
    # Optional spaces
    while i < n and s[i] == ' ':
        i += 1
    # Parse OP
    if i + 1 < n and s[i:i+2] in ('==', '!=', '<=', '>='):
        op = s[i:i+2]
        i += 2
    elif i < n and s[i] in ('<', '>'):
        op = s[i]
        i += 1
    else:
        raise ValueError(f"Invalid operator at position {i}")
    # Optional spaces
    while i < n and s[i] == ' ':
        i += 1
    # Parse LITERAL
    if i < n and s[i] == '"':
        text, i = _parse_string(s, i)
        literal = ('str', text)
    elif i < n and (s[i] == '-' or s[i].isdigit()):
        val, i = _parse_int(s, i)
        literal = ('int', val)
    else:
        raise ValueError(f"Invalid literal at position {i}")
    # Optional spaces before ]
    while i < n and s[i] == ' ':
        i += 1
    if i >= n or s[i] != ']':
        raise ValueError("Expected ']' to close filter")
    return ('filter', name, op, literal), i + 1


def _parse_bracket(s, i):
    n = len(s)
    if i >= n:
        raise ValueError("Unexpected end in bracket expression")

    if s[i] == '*':
        if i + 1 >= n or s[i + 1] != ']':
            raise ValueError("Expected ']' after '*'")
        return ('star',), i + 2

    if s[i] == '?':
        return _parse_filter(s, i + 1)

    if s[i] == '"':
        text, i = _parse_string(s, i)
        if i >= n or s[i] != ']':
            raise ValueError("Expected ']' after string")
        return ('key_str', text), i + 1

    # Slice or index
    if s[i] == ':':
        # [:B] or [:]
        i += 1
        if i < n and (s[i] == '-' or s[i].isdigit()):
            b, i = _parse_int(s, i)
        else:
            b = None
        if i >= n or s[i] != ']':
            raise ValueError("Expected ']' after slice")
        return ('slice', None, b), i + 1

    if s[i] == '-' or s[i].isdigit():
        a, i = _parse_int(s, i)
        if i < n and s[i] == ':':
            i += 1
            if i < n and (s[i] == '-' or s[i].isdigit()):
                b, i = _parse_int(s, i)
            else:
                b = None
            if i >= n or s[i] != ']':
                raise ValueError("Expected ']' after slice")
            return ('slice', a, b), i + 1
        else:
            if i >= n or s[i] != ']':
                raise ValueError("Expected ']' after integer index")
            return ('index', a), i + 1

    raise ValueError(f"Unexpected character '{s[i]}' in bracket expression")


def _parse_query(query):
    steps = []
    i = 0
    n = len(query)
    while i < n:
        if i + 1 < n and query[i] == '.' and query[i + 1] == '.':
            i += 2
            name, i = _parse_name(query, i)
            steps.append(('deep', name))
        elif query[i] == '.':
            i += 1
            name, i = _parse_name(query, i)
            steps.append(('key', name))
        elif query[i] == '[':
            i += 1
            step, i = _parse_bracket(query, i)
            steps.append(step)
        else:
            raise ValueError(f"Unexpected character '{query[i]}' at position {i}")
    return steps


def _deep_search(node, name):
    results = []
    if isinstance(node, dict):
        if name in node:
            results.append(node[name])
            results.extend(_deep_search(node[name], name))
        for v in node.values():
            results.extend(_deep_search(v, name))
    elif isinstance(node, list):
        for item in node:
            results.extend(_deep_search(item, name))
    return results


def _compare(value, op, literal):
    lit_type, lit_val = literal
    # Type mismatch check
    if isinstance(value, (dict, list)):
        return op == '!='
    if lit_type == 'int' and isinstance(value, str):
        return op == '!='
    if lit_type == 'str' and isinstance(value, int):
        return op == '!='
    if op == '==':
        return value == lit_val
    elif op == '!=':
        return value != lit_val
    elif op == '<':
        return value < lit_val
    elif op == '<=':
        return value <= lit_val
    elif op == '>':
        return value > lit_val
    elif op == '>=':
        return value >= lit_val
    return False


def _apply_step(node, step):
    kind = step[0]

    if kind == 'key':
        if isinstance(node, dict) and step[1] in node:
            return [node[step[1]]]
        return []

    if kind == 'key_str':
        if isinstance(node, dict) and step[1] in node:
            return [node[step[1]]]
        return []

    if kind == 'index':
        if isinstance(node, list):
            idx = step[1]
            if -len(node) <= idx < len(node):
                return [node[idx]]
        return []

    if kind == 'slice':
        if isinstance(node, list):
            a, b = step[1], step[2]
            return list(node[a:b])
        return []

    if kind == 'star':
        if isinstance(node, list):
            return list(node)
        elif isinstance(node, dict):
            return list(node.values())
        return []

    if kind == 'deep':
        return _deep_search(node, step[1])

    if kind == 'filter':
        _, name, op, literal = step
        if isinstance(node, list):
            results = []
            for item in node:
                if isinstance(item, dict) and name in item:
                    if _compare(item[name], op, literal):
                        results.append(item)
            return results
        return []

    return []
