from math import gcd


def spiral_position(n: int, first: int, grow: int, group: int, dirs: str) -> tuple[int, int]:
    # Validate dirs
    valid = set('NESW')
    if not dirs or any(c not in valid for c in dirs):
        raise ValueError("dirs must be a non-empty string over N, E, S, W")

    if n == 0:
        return (0, 0)

    d = len(dirs)

    def dir_vec(c):
        if c == 'E':
            return (1, 0)
        if c == 'W':
            return (-1, 0)
        if c == 'N':
            return (0, 1)
        return (0, -1)  # 'S'

    # S(j) = total steps in blocks 0..j-1
    # Block i (0-indexed) has 'group' legs each of length (first + i*grow)
    # S(j) = group * (j*first + grow * j*(j-1)//2)
    def S(j):
        return group * (j * first + grow * j * (j - 1) // 2)

    # Find largest j such that S(j) <= n
    if grow == 0:
        j = n // (group * first)
    else:
        # Binary search; upper bound: S(j) >= group*first*j, so j <= n//(group*first) suffices
        lo, hi = 0, n // (group * first) + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if S(mid) <= n:
                lo = mid
            else:
                hi = mid - 1
        j = lo

    # Robot is in block j; remaining steps after completing blocks 0..j-1
    remaining = n - S(j)
    L = first + j * grow  # leg length in block j

    # Number of complete legs in block j, and remainder
    q = remaining // L    # 0 <= q < group
    rem = remaining % L

    # --- Compute displacement from completed blocks 0..j-1 ---
    # Block i's direction pattern depends on (i*group) % d, which cycles with
    # period h = d / gcd(d, group) in i.
    h = d // gcd(d, group)

    # Precompute D[r] = sum of unit direction vectors for block r (r in 0..h-1)
    D = []
    for r in range(h):
        dx, dy = 0, 0
        for k in range(group):
            vx, vy = dir_vec(dirs[(r * group + k) % d])
            dx += vx
            dy += vy
        D.append((dx, dy))

    x, y = 0, 0
    for r in range(h):
        if r >= j:
            continue
        # i values in [0, j) with i mod h == r: r, r+h, r+2h, ...
        c = (j - 1 - r) // h + 1  # count
        # Sum of (first + (r + t*h)*grow) for t = 0..c-1
        # = c*first + grow*(c*r + h*c*(c-1)//2)
        total_len = c * first + grow * (c * r + h * c * (c - 1) // 2)
        x += D[r][0] * total_len
        y += D[r][1] * total_len

    # --- Completed legs in block j (legs at positions j*group .. j*group+q-1) ---
    for k in range(q):
        vx, vy = dir_vec(dirs[(j * group + k) % d])
        x += vx * L
        y += vy * L

    # --- Partial leg ---
    if rem > 0:
        vx, vy = dir_vec(dirs[(j * group + q) % d])
        x += vx * rem
        y += vy * rem

    return (x, y)
