import heapq
from typing import List, Tuple, Optional

def courier_cost(n: int, roads: List[Tuple[int, int, int]], depot: int,
                 jobs: List[Tuple[int, int, int]], capacity: int) -> Optional[int]:
    if not jobs:
        return 0

    m = len(jobs)

    # Check if any parcel is too large
    for job in jobs:
        if job[2] > capacity:
            return None

    # Floyd-Warshall all-pairs shortest paths
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for a, b, length in roads:
        if length < dist[a][b]:
            dist[a][b] = length
            dist[b][a] = length

    for k in range(n):
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            for j in range(n):
                dkj = dist[k][j]
                if dkj == INF:
                    continue
                nd = dik + dkj
                if nd < dist[i][j]:
                    dist[i][j] = nd

    # Relevant junctions (depot + all pickup/dropoff points)
    relevant_set = {depot}
    for job in jobs:
        relevant_set.add(job[0])
        relevant_set.add(job[1])
    relevant = sorted(relevant_set)
    rel_idx = {j: i for i, j in enumerate(relevant)}
    r = len(relevant)

    # Check all relevant junctions are reachable from depot
    for j in relevant:
        if dist[depot][j] == INF:
            return None

    mask_size = 1 << m
    all_delivered = mask_size - 1

    # Dijkstra on state space: (junction, in_van_mask, delivered_mask)
    # in_van & delivered must always be 0
    cost = [[[INF] * mask_size for _ in range(mask_size)] for _ in range(r)]

    start_j = rel_idx[depot]
    cost[start_j][0][0] = 0

    pq = [(0, start_j, 0, 0)]

    while pq:
        c, j, in_van, delivered = heapq.heappop(pq)
        if c > cost[j][in_van][delivered]:
            continue

        # Compute current load
        load = 0
        for i in range(m):
            if in_van & (1 << i):
                load += jobs[i][2]

        # Pick up jobs whose pickup is at this junction
        for i in range(m):
            if not (in_van & (1 << i)) and not (delivered & (1 << i)):
                if jobs[i][0] == relevant[j]:
                    if load + jobs[i][2] <= capacity:
                        ni = in_van | (1 << i)
                        if c < cost[j][ni][delivered]:
                            cost[j][ni][delivered] = c
                            heapq.heappush(pq, (c, j, ni, delivered))

        # Deliver jobs whose dropoff is at this junction
        for i in range(m):
            if in_van & (1 << i):
                if jobs[i][1] == relevant[j]:
                    ni = in_van & ~(1 << i)
                    nd = delivered | (1 << i)
                    if c < cost[j][ni][nd]:
                        cost[j][ni][nd] = c
                        heapq.heappush(pq, (c, j, ni, nd))

        # Drive to another relevant junction
        for k in range(r):
            if k == j:
                continue
            d = dist[relevant[j]][relevant[k]]
            if d == INF:
                continue
            nc = c + d
            if nc < cost[k][in_van][delivered]:
                cost[k][in_van][delivered] = nc
                heapq.heappush(pq, (nc, k, in_van, delivered))

    ans = cost[start_j][0][all_delivered]
    if ans == INF:
        return None
    return ans
