from collections import OrderedDict


class PinCache:
    """A cache limited by both number of entries and total weight,
    with pinning and two-level (COLD/WARM) eviction order."""

    COLD = "COLD"
    WARM = "WARM"

    def __init__(self, max_items: int, max_weight: int):
        self.max_items = max_items
        self.max_weight = max_weight
        # OrderedDict: key -> (value, weight, pinned, temperature)
        # Front = LRU, Back = MRU
        self._entries: OrderedDict = OrderedDict()

    # ── internal helpers ──────────────────────────────────────────────

    def _total_weight(self) -> int:
        return sum(w for (_, w, _, _) in self._entries.values())

    def _find_candidate(self, exclude_key=None):
        """Return the key of the next entry to evict, or None.
        COLD before WARM; within same temperature, LRU first."""
        best_key = None
        best_temp = None
        for k, (_, _, pinned, temp) in self._entries.items():
            if pinned:
                continue
            if k is exclude_key:
                continue
            if best_key is None:
                best_key = k
                best_temp = temp
            elif temp == self.COLD and best_temp == self.WARM:
                best_key = k
                best_temp = temp
            # same temperature → keep earlier (more LRU) one
        return best_key

    def _evict_until_fits(self, exclude_key=None):
        """Evict entries until both limits are satisfied.
        Returns list of evicted keys, or raises OverflowError."""
        evicted = []
        while (len(self._entries) > self.max_items
               or self._total_weight() > self.max_weight):
            candidate = self._find_candidate(exclude_key)
            if candidate is None:
                raise OverflowError("cannot meet cache limits")
            evicted.append(candidate)
            del self._entries[candidate]
        return evicted

    # ── public API ────────────────────────────────────────────────────

    def put(self, key, value, weight=1) -> list:
        if weight < 1 or weight > self.max_weight:
            raise ValueError(
                f"weight must be in [1, {self.max_weight}], got {weight}"
            )

        # Snapshot for rollback
        snapshot = OrderedDict(self._entries)

        # Store / update entry
        if key in self._entries:
            _, _, pinned, _ = self._entries[key]
            self._entries[key] = (value, weight, pinned, self.COLD)
        else:
            self._entries[key] = (value, weight, False, self.COLD)
        self._entries.move_to_end(key)

        # Evict if needed
        try:
            evicted = self._evict_until_fits(exclude_key=key)
        except OverflowError:
            self._entries = snapshot
            raise

        return evicted

    def get(self, key, default=None):
        if key in self._entries:
            val, w, pinned, _ = self._entries[key]
            self._entries[key] = (val, w, pinned, self.WARM)
            self._entries.move_to_end(key)
            return val
        return default

    def peek(self, key, default=None):
        if key in self._entries:
            return self._entries[key][0]
        return default

    def pin(self, key) -> bool:
        if key in self._entries:
            val, w, _, temp = self._entries[key]
            self._entries[key] = (val, w, True, temp)
            return True
        return False

    def unpin(self, key) -> bool:
        if key in self._entries:
            val, w, _, temp = self._entries[key]
            self._entries[key] = (val, w, False, temp)
            return True
        return False

    def drop(self, key) -> bool:
        if key in self._entries:
            del self._entries[key]
            return True
        return False

    def resize(self, max_items: int, max_weight: int) -> list:
        old_max_items = self.max_items
        old_max_weight = self.max_weight

        self.max_items = max_items
        self.max_weight = max_weight

        try:
            evicted = self._evict_until_fits(exclude_key=None)
        except OverflowError:
            self.max_items = old_max_items
            self.max_weight = old_max_weight
            raise

        return evicted

    def keys(self) -> list:
        return list(self._entries.keys())

    def stats(self) -> tuple:
        return (len(self._entries), self._total_weight())
