class Timeline:
    def __init__(self):
        self._texts = {0: ""}
        self._parent = {0: None}
        self._children = {0: []}
        self._current = 0
        self._next_id = 1
        self._preferred = {}  # rev -> preferred child id

    def _set_path_preferred(self):
        """After a successful operation, update preferred children along the path from root to current."""
        r = self._current
        while r is not None:
            p = self._parent[r]
            if p is not None:
                self._preferred[p] = r
            r = p

    def _get_path_to_current(self):
        path = []
        r = self._current
        while r is not None:
            path.append(r)
            r = self._parent[r]
        path.reverse()
        return path

    def _check_exists(self, rev):
        if rev not in self._texts:
            raise KeyError(rev)

    def write(self, s: str) -> int:
        rev_id = self._next_id
        self._next_id += 1
        self._texts[rev_id] = self._texts[self._current] + s
        self._parent[rev_id] = self._current
        self._children[rev_id] = []
        self._children[self._current].append(rev_id)
        self._current = rev_id
        self._set_path_preferred()
        return rev_id

    def erase(self, n: int) -> int:
        if n < 0 or n > len(self._texts[self._current]):
            raise ValueError(
                f"n={n} is invalid for text of length {len(self._texts[self._current])}"
            )
        rev_id = self._next_id
        self._next_id += 1
        if n == 0:
            self._texts[rev_id] = self._texts[self._current]
        else:
            self._texts[rev_id] = self._texts[self._current][:-n]
        self._parent[rev_id] = self._current
        self._children[rev_id] = []
        self._children[self._current].append(rev_id)
        self._current = rev_id
        self._set_path_preferred()
        return rev_id

    def undo(self) -> bool:
        if self._current == 0:
            return False
        self._current = self._parent[self._current]
        self._set_path_preferred()
        return True

    def redo(self) -> bool:
        if not self._children[self._current]:
            return False
        self._current = self._preferred[self._current]
        self._set_path_preferred()
        return True

    def checkout(self, rev: int):
        self._check_exists(rev)
        self._current = rev
        self._set_path_preferred()

    def text(self) -> str:
        return self._texts[self._current]

    def current(self) -> int:
        return self._current

    def parent(self, rev: int):
        self._check_exists(rev)
        return self._parent[rev]

    def children(self, rev: int) -> list:
        self._check_exists(rev)
        return sorted(self._children[rev])

    def log(self) -> list:
        return self._get_path_to_current()

    def distance(self, a: int, b: int) -> tuple:
        self._check_exists(a)
        self._check_exists(b)
        # Build ancestor set for a
        ancestors_a = set()
        r = a
        while r is not None:
            ancestors_a.add(r)
            r = self._parent[r]
        # Walk up from b to find LCA
        lca = b
        while lca is not None and lca not in ancestors_a:
            lca = self._parent[lca]
        # Count ups from a to lca
        ups = 0
        r = a
        while r != lca:
            r = self._parent[r]
            ups += 1
        # Count downs from lca to b
        downs = 0
        r = b
        while r != lca:
            r = self._parent[r]
            downs += 1
        return (ups, downs)

    def prune(self, rev: int) -> int:
        self._check_exists(rev)
        if rev == 0:
            raise ValueError("Cannot prune the root revision")
        # Check if current is rev or a descendant of rev
        r = self._current
        while r is not None:
            if r == rev:
                raise ValueError("Cannot prune the current revision or its ancestor")
            r = self._parent[r]

        # Collect all nodes to delete (rev and all descendants)
        to_delete = set()
        stack = [rev]
        while stack:
            node = stack.pop()
            to_delete.add(node)
            for child in self._children[node]:
                stack.append(child)

        count = len(to_delete)

        # Update the parent's children list
        parent_of_rev = self._parent[rev]
        self._children[parent_of_rev].remove(rev)

        # Handle preferred child of the parent
        if self._preferred.get(parent_of_rev) == rev:
            remaining = [c for c in self._children[parent_of_rev] if c not in to_delete]
            if remaining:
                self._preferred[parent_of_rev] = max(remaining)
            else:
                del self._preferred[parent_of_rev]

        # Remove all deleted nodes
        for node in to_delete:
            del self._texts[node]
            del self._parent[node]
            del self._children[node]
            if node in self._preferred:
                del self._preferred[node]

        return count
